  private def stringify(value: JsonValue, indent: Int): String = {
    val isPretty = indent >= 0
    val currentIndent = if (isPretty) "  " * indent else ""
    val nextIndent = if (isPretty) "  " * (indent + 1) else ""
    val newline = if (isPretty) "\n" else ""
    val space = if (isPretty) " " else ""

    value match {
      case JsonString(s) => s"\"${escapeString(s)}\""
      case JsonNumber(n) => if (n.isWhole) n.toLong.toString else n.toString
      case JsonBool(b) => b.toString
      case JsonNull => "null"
      case JsonArray(values) if values.isEmpty => "[]"
      case JsonArray(values) =>
        val items = values.map(v => nextIndent + stringify(v, if (isPretty) indent + 1 else -1))
        s"[$newline${items.mkString("," + newline)}$newline$currentIndent]"
      case JsonObject(fields) if fields.isEmpty => "{}"
      case JsonObject(fields) =>
        val items = fields.map { case (k, v) =>
          s"$nextIndent\"$k\":$space${stringify(v, if (isPretty) indent + 1 else -1)}"
        }
        s"{$newline${items.mkString("," + newline)}$newline$currentIndent}"
    }
  }

  private def escapeString(s: String): String =
    s.replace("\\", "\\\\").replace("\"", "\\\"").replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t")

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.")
    extractPath(value, parts.toList).map(tokenize)
  }

  private def extractPath(value: JsonValue, parts: List[String]): Option[JsonValue] = parts match {
    case Nil => Some(value)
